[package]
workspace = "../../../.."
name = "semio-hub-vcs"
version.workspace = true
edition.workspace = true
rust-version.workspace = true
description = "VCS plugin - one crate for the vcs artifact (diff/op/dsl/pack/spr/engine) and the vcs-play app (commands/modes/windows/panels)"

[lints]
workspace = true

[package.metadata.component]
package = "semio:vcs"

[package.metadata.semio]
deployment-directory = "🌿️vcs"
component-kind = "plugin"
role = "hub"

[[package.metadata.semio.playground]]
variant = "vcs"
ports = { react = 6075, wgpu = 6175 }

[lib]
crate-type = ["cdylib", "rlib"]
path = "🦀️.rs"

[[test]]
name = "native_openable_identity"
path = "../../🧪️tests/🪪️native-openable-identity/🦀️.rs"

[[test]]
name = "native_codecs"
path = "../../📇️native-codecs/🧪️tests/📇️native-codecs/🦀️.rs"

[dependencies]
semio-framework-value = { path = "../../../../../🧰️framework/🔨️modules/🌱️value/📦️packages/🦀️rust" }
semio-s-artifact-vcs-vcs = { workspace = true }
semio-framework-ui-contract.workspace = true
semio-framework-hash = { path = "../../../../../🧰️framework/🔨️modules/🔏️hash/📦️packages/🦀️rust", package = "semio-framework-hash" }
semio-hub-stdio = { workspace = true, default-features = false, features = ["full-artifact-catalog"] }
semio-s-artifact-stdio-csv = { workspace = true }
semio-s-artifact-stdio-json = { workspace = true }
semio-s-artifact-stdio-xlsx = { workspace = true }
semio-s-artifact-stdio-zip = { workspace = true }
semio-framework-os-kernel = { path = "../../../../../🧰️framework/🛍️products/💻️os/📦️packages/🦀️rust", package = "semio-framework-os-kernel" }
semio-framework = { path = "../../../../../🧰️framework/📦️packages/🦀️rust", package = "semio-framework" }
semio-framework-job = { path = "../../../../../🧰️framework/🔨️modules/🧵️job/📦️packages/🦀️rust", package = "semio-framework-job" }
semio-framework-plugin = { path = "../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/📦️packages/🦀️rust", features = ["component-guest"], package = "semio-framework-plugin" }
semio-framework-dispatch-macros = { path = "../../../../../🧰️framework/🔨️modules/🔀️dispatch/📦️packages/🦀️rust", package = "semio-framework-dispatch-macros" }
semio-framework-schema = { path = "../../../../../🧰️framework/🔨️modules/🧬️schema/📦️packages/🦀️rust", package = "semio-framework-schema" }
semio-framework-ui-scene = { path = "../../../../../🧰️framework/🔨️modules/🖱️ui/🎬️scene/📦️packages/🦀️rust", package = "semio-framework-ui-scene" }
semio-framework-value-derive = { path = "../../../../../🧰️framework/🔨️modules/🌱️value/✨️derive/📦️packages/🦀️rust", package = "semio-framework-value-derive" }


[dev-dependencies]
semio-framework-plugin = { path = "../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/📦️packages/🦀️rust", features = ["component-guest", "artifact-app-testing"], package = "semio-framework-plugin" }
serde.workspace = true
serde_json.workspace = true
semio-framework-async-macros = { path = "../../../../../🧰️framework/🔨️modules/⏳️async/✨️macros/📦️packages/🦀️rust" }


[package.metadata.semio.sources]
artifacts = ["../../../../../✏️s/🔌️plugins/🌿️vcs/🗿️artifacts"]

