[package]
workspace = "../../../.."
name = "semio-hub-space"
version.workspace = true
edition.workspace = true
rust-version.workspace = true
description = "S Studio plugin: OS host shell bundling the Home launcher and Studio apps"

[lints]
workspace = true

[package.metadata.component]
package = "semio:space"

[package.metadata.semio]
deployment-directory = "🪐️space"
component-kind = "plugin"
role = "hub"
capabilities = ["localBackboneStorage"]
host = { landing = "home", shell = "studio" }

[[package.metadata.semio.playground]]
variant = "s"
catalog-default = true
devContribution = "✏️s/🧑‍💻dev/🧬️schema/🔣️.json"
ports = { react = 6070, wgpu = 6066 }
user_ports = { react = [6072, 6073], wgpu = [6067, 6068] }

[[package.metadata.semio.playground]]
variant = "home"
app = "s.space.home@1/*#editor"
ports = { react = 6108, wgpu = 6208 }

[[package.metadata.semio.playground]]
variant = "space"
app = "s.space.space@1/*#editor"
ports = { react = 6109, wgpu = 6209 }

[lib]
crate-type = ["cdylib", "rlib"]
path = "../../🦀️.rs"

[features]
default = ["plugin-entry"]
plugin-entry = []

[dependencies]
semio-framework-pack-json = { path = "../../../../../🧰️framework/🔨️modules/🎒️pack/🔤️json/📦️packages/🦀️rust" }
