semio-framework-dsl = { path = "../../../../../🧰️framework/🔨️modules/🗣️dsl/📦️packages/🦀️rust" }
semio-framework-ui-locale = { path = "../../../../../🧰️framework/🔨️modules/🖱️ui/🌐️locale/📦️packages/🦀️rust" }
semio-s-artifact-draw-drawing = { path = "../../../../../✏️s/🔌️plugins/🖍️draw/🗿️artifacts/🖍️drawing/📦️packages/🦀️rust" }
semio-s-artifact-writer-writer = { path = "../../../../../✏️s/🔌️plugins/✒️writer/🗿️artifacts/✒️writer/📦️packages/🦀️rust" }
semio-framework-schema-registry = { path = "../../../../../🧰️framework/🔨️modules/🧬️schema/📇️registry/📦️packages/🦀️rust" }
semio-framework-2d = { path = "../../../../../🧰️framework/🔨️modules/◻️2d/📦️packages/🦀️rust", default-features = false }
semio-framework-value = { path = "../../../../../🧰️framework/🔨️modules/🌱️value/📦️packages/🦀️rust" }
semio-s-artifact-space-home = { workspace = true, features = ["component-app-assembly"] }
semio-s-artifact-space-space = { workspace = true, features = ["component-app-assembly"] }
semio-framework-artifact-infinite-dag = { workspace = true }
semio-framework-artifact-space-space = { workspace = true }
infinite_canvas = { path = "../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/♾️infinite/📦️packages/🦀️rust", package = "semio-framework-os-infinite" }
semio-framework-os-kernel = { workspace = true }
semio-framework-plugin = { workspace = true, features = ["component-guest"] }
semio-framework-dispatch-macros = { workspace = true }
semio-framework = { workspace = true }
semio-framework-job.workspace = true
semio-framework-schema = { workspace = true }
semio-framework-value-derive = { workspace = true }
pack = { workspace = true }
base64_codec = { path = "../../../../../🧰️framework/🔨️modules/🚪️io/🔤️base64/📦️packages/🦀️rust", package = "semio-framework-io-base64" }
semio-framework-artifact-workflow-workflow = { path = "../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔁️workflow/🗿️artifacts/🔁️workflow/📦️packages/🦀️rust" }
semio-framework-tool-machine = { path = "../../../../../🧰️framework/🔨️modules/🛠️tool-machine/📦️packages/🦀️rust" }
semio-framework-ui-contract = { workspace = true }
