[package]
workspace = "../../../../../.."
name = "semio-s-artifact-procedural-generation3d"
version.workspace = true
edition.workspace = true
rust-version.workspace = true
description = "Procedural generation3d artifact"

[package.metadata.semio]
role = "artifact"

[lints]
workspace = true

[lib]
path = "../../🦀️.rs"

[features]
default = []
component-app-assembly = ["semio-framework-plugin/component-guest", "dep:machine", "dep:semio-framework-tool-machine", "dep:semio-framework-dispatch-macros", "dep:semio-framework-os-flow", "dep:semio-framework-os-infinite", "dep:semio-framework-ui", "dep:semio-framework-ui-contract", "dep:semio-framework-ui-styling"]

[dependencies]
semio-framework-pack-json = { path = "../../../../../../../🧰️framework/🔨️modules/🎒️pack/🔤️json/📦️packages/🦀️rust" }
semio-framework-diagnostic = { path = "../../../../../../../🧰️framework/🔨️modules/⚠️diagnostic/📦️packages/🦀️rust" }
semio-framework-dsl = { path = "../../../../../../../🧰️framework/🔨️modules/🗣️dsl/📦️packages/🦀️rust" }
semio-framework-ui-locale = { path = "../../../../../../../🧰️framework/🔨️modules/🖱️ui/🌐️locale/📦️packages/🦀️rust" }
semio-framework-schema-composition = { path = "../../../../../../../🧰️framework/🔨️modules/🧬️schema/🧩️composition/📦️packages/🦀️rust" }
semio-framework-schema-state = { path = "../../../../../../../🧰️framework/🔨️modules/🧬️schema/📶️state/📦️packages/🦀️rust" }
semio-framework-schema-registry = { path = "../../../../../../../🧰️framework/🔨️modules/🧬️schema/📇️registry/📦️packages/🦀️rust" }
semio-framework-2d = { path = "../../../../../../../🧰️framework/🔨️modules/◻️2d/📦️packages/🦀️rust", default-features = false }
semio-framework-value = { path = "../../../../../../../🧰️framework/🔨️modules/🌱️value/📦️packages/🦀️rust" }
semio-framework-artifact-flow-flow = { workspace = true }
semio-framework-artifact-infinite-dag = { workspace = true }
semio-framework-artifact-playbook-playbook = { workspace = true }
semio-framework = { workspace = true }
semio-framework-job = { workspace = true }
semio-framework-os-kernel = { workspace = true }
semio-framework-plugin = { workspace = true }
semio-framework-schema = { workspace = true }
semio-framework-tool-run = { workspace = true }
semio-framework-value-derive = { workspace = true }
semio-s-artifact-stdio-dwg = { workspace = true }
semio-s-artifact-stdio-gltf = { workspace = true }
semio-s-artifact-stdio-json = { workspace = true }
semio-s-artifact-stdio-las = { workspace = true }
semio-s-artifact-stdio-obj = { workspace = true }
semio-s-artifact-stdio-ply = { workspace = true }
semio-s-artifact-stdio-png = { workspace = true }
# 🔺️ `conversion-mesh` mounts `s.stdio.semio@v1/mesh`'s own tested per-format bridges
# (`SemioMeshTo{Stl,Obj,Ply,Gltf,Las,Dwg}` and their inverses), which every 🚪️io mesh leaf composes
# instead of re-deriving a file grammar — ticket 26/09/09/PROCEDURAL-3D-END-TO-END.
semio-s-artifact-stdio-semio = { workspace = true, features = ["conversion-mesh"] }
semio-s-artifact-stdio-stl = { workspace = true }
semio-s-artifact-stdio-txt = { workspace = true }
pack = { workspace = true }
serde_json = { workspace = true }
semio-framework-dispatch-macros = { workspace = true, optional = true }
# 🛠️ Gestures are `🔄️machine` statecharts folded by the tool-machine runner (design §5, §13); `statechart!` expands to
# `machine::…`, hence the rename.
machine = { path = "../../../../../../../🧰️framework/🔨️modules/🔄️machine/📦️packages/🦀️rust", package = "semio-framework-machine", default-features = false, features = ["macros"], optional = true }
semio-framework-tool-machine = { workspace = true, optional = true }
semio-framework-os-flow = { workspace = true, optional = true }
semio-framework-os-infinite = { workspace = true, optional = true }
semio-framework-ui = { workspace = true, optional = true, features = ["wgpu"] }
semio-framework-ui-contract = { workspace = true, optional = true }
semio-framework-ui-styling = { workspace = true, optional = true }

[dev-dependencies]
syn = { version = "=2.0.117", features = ["full", "visit"] }
proc-macro2 = "1"
semio-framework-plugin = { workspace = true, features = ["artifact-app-testing"] }
semio-framework-os-kernel = { workspace = true, features = ["protocol-laws"] }
semio-framework-async-macros = { workspace = true }
# 🧮️ The heap witness the guest-memory laws weigh the contributions install path with — test-only,
# never a `[dependencies]` entry: a production guest reads its own footprint with `memory.size`.
semio-framework-trace = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }
# 🔬️ Headless example-geometry harness (`[[test]] example-geometry`): the flow host + the two
# packaged flow extensions whose operators every bundled example's `neuron-kind` chain resolves to.
# Test-only — the artifact crate itself never links a geometry kernel.
semio-framework-os-flow = { workspace = true }
# ⚖️ Third-party differential oracle for the same harness — `parry3d` recomputes every tessellated
# example's volume, centre of mass, and bounding box from the triangle soup our kernel emitted, so a
# committed expected-stat is never only our own arithmetic. Test-only, never a `[dependencies]`
# entry, never reachable from a production target (same standing as `semio-framework-3d`'s).
parry3d = "0.17"
# 🪪️ Third-party oracle for the preview evaluation run's node entity key (FNV-1a 64) — test-only.
fnv = "1.0.7"

# 🧪️ Emoji file names never compile as an implicit `tests/` target, so the example-geometry lane is
# declared with an explicit ASCII name and a package-root-relative path.

# 🔁️ The 🚪️io round-trip lane: one committed unit cube through all nine format leaves, with
# `parry3d` as the third-party check on every recovered mesh. Its per-format cases live beside the
# leaves they exercise; this entry point only mounts them (see that file's own doc comment).
[[test]]
name = "io-round-trip"
path = "../../🏅️standards/🔖️1/🪆️subsets/✳️any/🚪️io/🧪️tests/🔁️round-trip/🦀️.rs"

# 🔁️ The incremental re-evaluation lane: what ONE slider edit costs the chain, on the real hex
# column with the packaged operators installed — dirty-set precision, the tessellation cache, the
# painted evaluation and the hop's own UI scope.

