semio-s-artifact-stdio-wav = { workspace = true, optional = true }
semio-s-artifact-stdio-xml = { workspace = true, optional = true }
semio-s-artifact-stdio-zip = { workspace = true, optional = true }
# /🧩️ Capability Dependencies
serde = { workspace = true }
serde_json = { workspace = true }

[dev-dependencies]
semio-framework-plugin = { workspace = true, features = ["artifact-app-testing"] }
# 🔮 Test-only geometry ORACLE (never a `[dependencies]` entry, never reachable from a
# production target) — same crate and version `semio-framework-3d` already uses as its collision
# oracle. `🧲️procedural-example-booleans` measures the tessellated boolean result with parry3d's
# own signed-volume integrator to cross-check this kernel's `solid_volume`.
parry3d = "0.17"
# 🔮 Test-only EXACT-ARITHMETIC oracle for `🧊️brep/…/➡️vector/⚖️predicates` (never a
# `[dependencies]` entry, never reachable from a production target). The predicates' exact path is
# nonoverlapping floating-point expansion arithmetic (Shewchuk error-free transformations); this
# recomputes the SAME determinants in arbitrary-precision rationals — a completely different
# representation and a completely different algorithm, written by someone else — so the claim "the
# expansion path returns the exact sign" rests on an independent derivation rather than on the
# expansion code agreeing with itself (ticket 26/09/09/PROCEDURAL-3D-END-TO-END,
# `📓️kernel-performance-2026-09-13.md`).
num-rational = "0.4"
# 🔮 Test-only RASTER oracle (never a `[dependencies]` entry): resvg renders the svg leaf's output
# of the same drawing the `🖊️drawing → 📷️png` rasterizer paints, and hayro renders the pdf leaf's
# output, so neither raster expectation is computed by this repository's own code.
resvg = "0.45.1"
hayro = "0.4.0"
semio-framework-async-macros = { workspace = true }
semio-s-artifact-stdio-csv = { workspace = true }
semio-s-artifact-stdio-json = { workspace = true }

[[test]]
name = "flow_retained_decode"
path = "../../🏅️standards/🔖️v1/🪆️subsets/🌊️flow/🧬️schema/📸️snapshot/💾️binary/🧪️tests/💾️binary/🦀️.rs"

[[test]]
name = "brep_procedural_example_booleans"
path = "../../🏅️standards/🔖️v1/🪆️subsets/🧊️brep/🧪️tests/🧲️procedural-example-booleans/🦀️.rs"

# 📦️ Extrude/sweep prism ORIENTATION laws — ticket 26/09/09/PROCEDURAL-3D-END-TO-END. Two profile
# shapes × both windings × both sweep directions × both profile-coedge senses, each held to outward
# face normals and a POSITIVE tessellated signed volume equal to the closed form, with `parry3d` as
# the third-party integrator.
[[test]]
name = "brep_extrude_orientation"
path = "../../🏅️standards/🔖️v1/🪆️subsets/🧊️brep/🧪️tests/📦️extrude-orientation/🦀️.rs"

# ⏱️ Resumable tessellator + validate-gate laws — ticket 26/09/09/PROCEDURAL-3D-END-TO-END. Declared
# as its own `[[test]]` (rather than a `#[cfg(test)]` module) so the interactive-job contract stays
# runnable from the crate's PUBLIC surface alone, independent of the lib's own test target.
[[test]]
name = "brep_tessellation_jobs"
path = "../../🏅️standards/🔖️v1/🪆️subsets/🧊️brep/🧪️tests/⏱️tessellation-jobs/🦀️.rs"

# 🎨️ ANALYTIC blend laws — ticket 26/09/09/PROCEDURAL-3D-END-TO-END. Constant-radius rolling-ball
# fillets as `Surface::Cylinder` edge patches and `Surface::Sphere` corner patches, chamfers as
# planar cut faces, over the full 12-edge box and every partial selection, each held to χ = 2, a
# silent `validate_body`, an outward shell, its Steiner closed-form volume, and `parry3d`'s own
# integration of the tessellated result — plus the interactive wall-clock budget the NURBS patches
# this rewrite replaced could not meet.
[[test]]
name = "brep_analytic_blend"
path = "../../🏅️standards/🔖️v1/🪆️subsets/🧊️brep/🧪️tests/🎨️analytic-blend/🦀️.rs"

[[test]]
name = "brep_shell_orientation"
path = "../../🏅️standards/🔖️v1/🪆️subsets/🧊️brep/🧪️tests/🐚️shell-orientation/🦀️.rs"

